(7396523, 1163653, 114285, '<td valign="top">This is my favourite by far in the whole challenge. Gorgeous scenery lovely pink and golden mist and beautiful beautiful light!! Pretty sure it will ribbon, I hope so for your sake anyway!</td>', 'This is my favourite by far in the whole challenge. Gorgeous scenery lovely pink and golden mist and beautiful beautiful light!! Pretty sure it will ribbon, I hope so for your sake anyway!', '2015-08-11 05:06:57.000000', NULL, 1),
(7396524, 1163632, 114285, '<td valign="top">This is my 2nd fave of the challenge, extremely brilliant light and wonderful editing with added texture well done!</td>', 'This is my 2nd fave of the challenge, extremely brilliant light and wonderful editing with added texture well done!', '2015-08-11 05:07:59.000000', NULL, 1),
