(7397654, 1163142, 61396, '<td valign="top">I like finding stuff in an apparently simple image.<br/> <br/><a href="//www.dpchallenge.com/image.php?IMAGE_ID=1154421" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/60000-64999/61396/120/Copyrighted_Image_Reuse_Prohibited_1154421.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/60000-64999/61396/120/Copyrighted_Image_Reuse_Prohibited_1154421.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/60000-64999/61396/120/Copyrighted_Image_Reuse_Prohibited_1154421.jpg"/></a></td>', 'I like finding stuff in an apparently simple image. ', '2015-08-16 16:47:59.000000', NULL, 1),
